// Body holds exactly one decoded document root.
type Body struct {
	Family       string
	Environment  *EnvironmentCapabilityManifest
	Observation  *ObservationIR
	Semantic     *SemanticIR
	Operation    *OperationContract
	Presentation *PresentationIR
	Version      *VersionManifest
}

func decodeBody(family string, v any, path string, ctx rt.Ctx) (Body, error) {
	out := Body{Family: family}
	switch family {
	case "environment":
		x, err := DecodeEnvironmentCapabilityManifest(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Environment = &x
	case "observation":
		x, err := DecodeObservationIR(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Observation = &x
	case "semantic":
		x, err := DecodeSemanticIR(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Semantic = &x
	case "operation":
		x, err := DecodeOperationContract(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Operation = &x
	case "presentation":
		x, err := DecodePresentationIR(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Presentation = &x
	case "version":
		x, err := DecodeVersionManifest(v, path, ctx)
		if err != nil {
			return Body{}, err
		}
		out.Version = &x
	default:
		return Body{}, rt.Fail(path, "schema.unknown")
	}
	return out, nil
}

func (b Body) Encode() any {
	switch b.Family {
	case "environment":
		return b.Environment.Encode()
	case "observation":
		return b.Observation.Encode()
	case "semantic":
		return b.Semantic.Encode()
	case "operation":
		return b.Operation.Encode()
	case "presentation":
		return b.Presentation.Encode()
	case "version":
		return b.Version.Encode()
	}
	return nil
}
